   self.delay[ids]=torch.randint(0,2,(len(ids),),device=self.device,generator=self.rng) if self.enabled else 0
   self.episode[ids]+=1
   for c in self.cache.values():c['last'][ids]=-1;c['sample_tick'][ids]=-1;c['ready'][ids]=False
